import{_ as t,o,c as r,ae as a}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Reserved repository directories","description":"","frontmatter":{"id":"9316364013","title":"Reserved repository directories","state":"Approved","created":"2026-10-07T00:00:00.000Z","tags":["directory","mise","github-actions","devops","protobuf","wit","opentelemetry"],"category":"Platform"},"headers":[],"relativePath":"adrs/9316364013/README.md","filePath":"adrs/9316364013/README.md"}'),s={name:"adrs/9316364013/README.md"};function d(i,e,n,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="reserved-repository-directories" tabindex="-1">Reserved repository directories <a class="header-anchor" href="#reserved-repository-directories" aria-label="Permalink to &quot;Reserved repository directories&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Every repository carries files that belong to no single language workspace: task scripts, scripts run by GitHub Actions, operational assets and schema sources. Without a reserved place for each, every repository invents its own, tooling paths drift, and the layout has to be learned again on every clone.</p><p>Two rules settle the names. A directory is named after what it holds, never after the tool that processes it. Inside a reserved directory the layout is whatever the consuming tool dictates, so no second naming decision exists.</p><p>This ADR fixes the set of reserved directories. The layout inside each one is decided by the ADR that owns it, linked from the table.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li><p>You <strong>MUST</strong> reserve the following directories at the repository root, with the meaning given, in every repository regardless of language or shape:</p><table tabindex="0"><thead><tr><th>Directory</th><th>Holds</th><th>Layout</th></tr></thead><tbody><tr><td><code>.config/&lt;tool&gt;/</code></td><td>configuration that drives a tool</td><td>the tool&#39;s own layout</td></tr><tr><td><code>.config/mise/</code></td><td>mise tasks and code they share</td><td><a href="./../6647967335/README.html">ADR#6647967335</a></td></tr><tr><td><code>devops/</code></td><td>operational assets that reach nothing live</td><td><a href="./../2078011537/README.html">ADR#2078011537</a></td></tr><tr><td><code>devops/infra/</code></td><td>the live estate: Terragrunt and GitOps</td><td><a href="./../6561361204/README.html">ADR#6561361204</a></td></tr><tr><td><code>proto/</code>, <code>wit/</code>, <code>otel/</code></td><td>schema sources, one directory per language</td><td><a href="./../4711775939/README.html">ADR#4711775939</a></td></tr><tr><td><code>openapi/</code>, <code>asyncapi/</code></td><td>interface documents, one per specification</td><td><a href="./../1427717799/README.html">ADR#1427717799</a></td></tr><tr><td><code>&lt;extension&gt;workspace/</code></td><td>one language toolchain each</td><td><a href="./../5842232571/README.html">ADR#5842232571</a></td></tr><tr><td><code>projects/</code></td><td>isolated projects</td><td><a href="./../0752163629/README.html">ADR#0752163629</a></td></tr></tbody></table></li><li><p>You <strong>MUST NOT</strong> reuse a reserved directory name for another purpose at the repository root, and you <strong>MUST NOT</strong> place these files anywhere else unless the ADR that owns the directory allows it.</p></li><li><p>You <strong>MUST NOT</strong> name a reserved directory after the tool that processes it. <code>.config/&lt;tool&gt;/</code> and <code>devops/&lt;tool&gt;/</code> are the exceptions, because each holds nothing but what that one tool reads.</p></li><li><p>You <strong>MUST</strong> follow the consuming tool&#39;s own layout inside a reserved directory and <strong>MUST NOT</strong> add a naming layer of your own.</p></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../6647967335/README.html">ADR#6647967335</a>: mise tasks and shared code</li><li><a href="./../2078011537/README.html">ADR#2078011537</a>: Operational assets</li><li><a href="./../6561361204/README.html">ADR#6561361204</a>: Live infrastructure</li><li><a href="./../4711775939/README.html">ADR#4711775939</a>: Schema source directories</li><li><a href="./../1427717799/README.html">ADR#1427717799</a>: OpenAPI and AsyncAPI documents</li><li><a href="./../5842232571/README.html">ADR#5842232571</a>: Language workspaces</li><li><a href="./../0752163629/README.html">ADR#0752163629</a>: Project namespaces</li></ul>',9)])])}const f=t(s,[["render",d]]);export{u as __pageData,f as default};
